<summary>proof-live.mjs</summary>

```js
import { spawnSync } from "node:child_process";
import fs from "node:fs";
import { createRequire } from "node:module";
import os from "node:os";
import path from "node:path";
import { pathToFileURL } from "node:url";

const repoRoot = process.cwd();

async function runChild() {
  const caseName = process.argv[3];
  const proofCase = buildCase(caseName);
  const require = createRequire(path.join(repoRoot, "package.json"));
  const { Command } = require("commander");
  const tempDir = fs.mkdtempSync(path.join(os.tmpdir(), "openclaw-voice-call-tail-proof-"));
  const logFile = path.join(tempDir, "custom.log");
  fs.writeFileSync(logFile, proofCase.initial);
  const initialByteLength = Buffer.isBuffer(proofCase.initial)
    ? proofCase.initial.length
    : Buffer.byteLength(proofCase.initial, "utf8");

  const originalReadSync = fs.readSync.bind(fs);
  let shortReadTriggered = false;
  fs.readSync = function patchedReadSync(fd, buffer, offset, length, position) {
    if (
      !shortReadTriggered &&
      proofCase.firstReadBytes !== null &&
      typeof position === "number" &&
      position === initialByteLength &&
      Buffer.isBuffer(buffer)
    ) {
      shortReadTriggered = true;
      return originalReadSync(fd, buffer, offset, proofCase.firstReadBytes, position);
    }
    return originalReadSync(fd, buffer, offset, length, position);
  };

  const captured = [];
  const originalWrite = process.stdout.write.bind(process.stdout);
  process.stdout.write = ((chunk, encoding, cb) => {
    captured.push(String(chunk));
    if (typeof cb === "function") cb();
    return true;
  });

  const { registerVoiceCallCli } = await import(
    pathToFileURL(path.join(repoRoot, "extensions/voice-call/src/cli.ts")).href
  );
  const program = new Command();
  registerVoiceCallCli({
    program,
    config: {},
    ensureRuntime: async () => ({ manager: {} }),
    logger: { info() {}, warn() {}, error() {}, debug() {} },
  });

  setTimeout(() => fs.appendFileSync(logFile, proofCase.appended), 20);
  setTimeout(() => {
    process.stdout.write = originalWrite;
    fs.readSync = originalReadSync;
    fs.rmSync(tempDir, { recursive: true, force: true });
    const output = captured.join("");
    const printedExpectedLines = proofCase.expectedLines.every((line) => output.includes(`${line}\n`));
    const emittedReplacement = output.includes("\ufffd");
    const emittedFragment = proofCase.forbiddenFragments.some((line) => output.includes(line));
    originalWrite(`case: ${caseName}\n`);
    originalWrite(`short-read-triggered: ${shortReadTriggered}\n`);
    originalWrite(`printed-expected-lines: ${printedExpectedLines}\n`);
    originalWrite(`emitted-replacement-character: ${emittedReplacement}\n`);
    originalWrite(`emitted-partial-fragment: ${emittedFragment}\n`);
    originalWrite(`raw-output: ${JSON.stringify(output)}\n`);
    process.exit(
      shortReadTriggered === proofCase.expectShortRead &&
        printedExpectedLines &&
        !emittedReplacement &&
        !emittedFragment
        ? 0
        : 1,
    );
  }, 350);

  void program.parseAsync(["voicecall", "tail", "--file", logFile, "--since", "0", "--poll", "50"], {
    from: "user",
  });
}

function buildCase(caseName) {
  const eAcute = Buffer.from("é", "utf8");
  const cases = {
    newline: {
      initial: "initial\n",
      appended: "first\nsecond\n",
      firstReadBytes: Buffer.byteLength("first\n", "utf8"),
      expectedLines: ["first", "second"],
      forbiddenFragments: [],
      expectShortRead: true,
    },
    "mid-record": {
      initial: "initial\n",
      appended: '{"event":"first"}\n{"event":"second"}\n',
      firstReadBytes: Buffer.byteLength('{"event":"fir', "utf8"),
      expectedLines: ['{"event":"first"}', '{"event":"second"}'],
      forbiddenFragments: ['{"event":"fir\n'],
      expectShortRead: true,
    },
    multibyte: {
      initial: "initial\n",
      appended: '{"word":"café"}\n',
      firstReadBytes: Buffer.byteLength('{"word":"caf', "utf8") + 1,
      expectedLines: ['{"word":"café"}'],
      forbiddenFragments: [],
      expectShortRead: true,
    },
    "startup-record": {
      initial: '{"event":"sta',
      appended: 'rt"}\n',
      firstReadBytes: null,
      expectedLines: ['{"event":"start"}'],
      forbiddenFragments: ['{"event":"sta\n'],
      expectShortRead: false,
    },
    "startup-multibyte": {
      initial: Buffer.concat([Buffer.from('{"word":"caf', "utf8"), eAcute.subarray(0, 1)]),
      appended: Buffer.concat([eAcute.subarray(1), Buffer.from('"}\n', "utf8")]),
      firstReadBytes: null,
      expectedLines: ['{"word":"café"}'],
      forbiddenFragments: [],
      expectShortRead: false,
    },
  };
  const proofCase = cases[caseName];
  if (!proofCase) throw new Error(`Unknown proof case: ${caseName}`);
  return proofCase;
}

function runParent() {
  const cases = ["newline", "mid-record", "multibyte", "startup-record", "startup-multibyte"];
  console.log("entrypoint: registerVoiceCallCli voicecall tail --file custom.log");
  for (const proofCase of cases) {
    const result = spawnSync(process.execPath, ["--import", "tsx", import.meta.filename, "--child", proofCase], {
      cwd: repoRoot,
      encoding: "utf8",
      stdio: ["ignore", "pipe", "pipe"],
    });
    process.stdout.write(result.stdout);
    process.stderr.write(result.stderr);
    if (result.status !== 0) {
      process.exit(result.status ?? 1);
    }
  }
}

if (process.argv[2] === "--child") {
  await runChild();
} else {
  runParent();
}
```

